442	std::optional<ObjectMetadata> S3ObjectStorage::tryGetObjectMetadata(const std::string & path, bool with_tags) const
443	{
444	    auto settings_ptr = s3_settings.get();
445	    auto object_info = S3::getObjectInfoIfExists(*client.get(), uri.bucket, path, {}, /* with_metadata= */ true, with_tags);
446	
447	    if (object_info.size == 0 && object_info.last_modification_time == 0 && object_info.metadata.empty())
448	        return {};
449	
450	    ObjectMetadata result;
451	    result.size_bytes = object_info.size;
452	    result.last_modified = Poco::Timestamp::fromEpochTime(object_info.last_modification_time);
453	    result.etag = object_info.etag;
454	    result.tags = object_info.tags;
455	    result.attributes = object_info.metadata;
456	
457	    return result;
458	}
