460	ObjectMetadata S3ObjectStorage::getObjectMetadata(const std::string & path, bool with_tags) const
461	{
462	    auto settings_ptr = s3_settings.get();
463	    S3::ObjectInfo object_info;
464	    try
465	    {
466	        object_info = S3::getObjectInfo(*client.get(), uri.bucket, path, /*version_id=*/ {}, /*with_metadata=*/ true, /*with_tags=*/ with_tags);
467	    }
468	    catch (DB::Exception & e)
469	    {
470	        bool updated = false;
471	        if (credentials_refresh_callback)
472	        {
473	            auto new_client = credentials_refresh_callback();
474	            if (new_client)
475	            {
476	                client.set(std::move(new_client));
477	                object_info = S3::getObjectInfo(*client.get(), uri.bucket, path, /*version_id=*/ {}, /*with_metadata=*/ true, /*with_tags=*/ with_tags);
478	                updated = true;
479	            }
480	        }
481	        if (!updated)
482	        {
483	            e.addMessage("while reading " + path);
484	            throw;
485	        }
486	    }
487	
488	    ObjectMetadata result;
489	    result.size_bytes = object_info.size;
490	    result.last_modified = Poco::Timestamp::fromEpochTime(object_info.last_modification_time);
491	    result.etag = object_info.etag;
492	    result.tags = std::move(object_info.tags);
493	    result.attributes = object_info.metadata;
494	
495	    return result;
496	}

